    "type_prefix": "Тип ",
    "polarity_desc_A": "Прямой кабель. Key-up на конце A, key-down на конце B. Переворот разъема на конце B инвертирует ряд волокон — позиция n на конце A соответствует позиции (total+1−n) на конце B.",
    "polarity_desc_B": "Перевернутый кабель (key-up к key-up). Позиция волокна n на конце A напрямую соответствует позиции n на конце B. Изготавливается с одним внутренне перевернутым разъемом для компенсации инверсии ряда.",
    "polarity_desc_C": "Кабель с перекрещенными парами. Key-up на конце A, key-down на конце B. Последовательные пары волокон переставляются перед переворотом конечного разъема — используется там, где кассетные модули требуют перераспределения пар.",
