    "t568a_desc": "T568A — Рекомендуется для жилых помещений и горизонтальных линий (TIA-568). Зеленая пара на контактах 1–2. Пары 2 и 3 идут в обратном порядке по сравнению с T568B.",
    "t568b_desc": "T568B — Доминирует в коммерческих сетях Северной Америки. Оранжевая пара на контактах 1–2. Электрически идентичен T568A с переставленными парами 2 и 3.",
