    "sysctl_title": "Настройка TCP в Linux (sysctl)",
    "sysctl_subtitle": "Генерация команд sysctl для настройки буферов TCP Linux и контроля перегрузки для параметров вашего пути.",
    "sysctl_algo": "Алгоритмы контроля перегрузки",
    "sysctl_apply_hint": "Применить: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Значения рассчитываются на основе вашего BDP.",
    "ref_title": "Справка по алгоритмам",
    "ref_reno_desc": "Классический алгоритм AIMD. Медленный старт удваивает cwnd каждый RTT до ssthresh. Предотвращение перегрузки добавляет ~1 сегмент за RTT. При 3 дублирующих ACK: ssthresh = cwnd/2, cwnd = ssthresh. При тайм-ауте: cwnd = 1 MSS. Справедлив, но плохо использует пути с высоким BDP после потери.",
    "ref_cubic_desc": "По умолчанию в Linux. Использует кубическую функцию W(t) = C(t-K)^3 + W_max (C=0.4, beta=0.7). После потери cwnd падает до 70% от W_max, затем растет по вогнуто-выпуклой кривой. Более агрессивен, чем Reno, в сетях с большой задержкой. K = (W_max * 0.3 / C)^(1/3).",
    "ref_bbr_desc": "Алгоритм на основе модели от Google. Оценивает пропускную способность узкого места и минимальный RTT вместо использования потери как сигнала. Фазы: Startup (усиление 2.89x), Drain, ProbeBW (8-фазный цикл усиления: 1.25/0.75/1...), ProbeRTT (4 сегмента каждые ~10с). Достигает полной пропускной способности даже при потерях.",
