    "cni_policy": "Сетевая политика",
    "cni_perf": "Производительность",
    "cni_enc": "Шифрование",
    "cni_usecase": "Лучше всего для",
    "cni_vs_docker": "Сети Docker ограничены хостом (bridge) или кластером (overlay). Плагины CNI K8s обеспечивают плоскую сеть по всему кластеру, где каждый под получает маршрутизируемый IP без NAT.",
    "desc_bridge": "Программный мост на хосте Docker — режим по умолчанию. Контейнеры делят одну подсеть, NAT для выхода в сеть. Лучшее решение для одиночных хостов.",
    "desc_overlay": "Overlay на нескольких хостах через VXLAN — требует Docker Swarm. Контейнеры на разных хостах видны в одном L2-сегменте.",
    "desc_macvlan": "Контейнер получает свой MAC и IP напрямую в L2-сегменте родительской сетевой карты. Без NAT, без моста. Идеально для старого ПО, требующего прямого доступа к L2.",
    "desc_ipvlan": "Похоже на MACVLAN, но контейнеры делят родительский MAC. Режим L3 маршрутизирует IP контейнеров — устраняет риск ARP-штормов в больших сетях.",
    "desc_host": "Контейнер использует сетевой стек хоста напрямую — без изоляции, макс. скорость. Для задач, чувствительных к задержкам (например, агенты мониторинга).",
    "desc_none": "Нет сетевых интерфейсов, кроме петли (loopback). Полная изоляция. Если контейнеру не нужен доступ в сеть.",
