    "proto_sftp_notes": "Протокол передачи файлов SSH. Стандартный защищённый транспорт. Немного медленнее SCP из-за служебного трафика протокола.",
    "proto_tftp_notes": "Trivial FTP. Поблочная передача в режиме lockstep. Сильная зависимость от задержки. Стандартный размер блока ограничивает скорость ~1,5 - 3,5 Mbps.",
    "proto_ftp_notes": "Протокол передачи файлов. Очень низкие накладные расходы, быстро, но без шифрования. Учётные данные передаются в открытом виде.",
    "proto_http_notes": "Протокол передачи гипертекста. Быстрый, низкие накладные расходы. Отлично подходит для локальных промежуточных серверов.",
    "proto_https_notes": "Защищённый HTTP. Стандарт для современных загрузок ZTP / из облака. Умеренные криптографические накладные расходы.",
    "plat_iosxe": "Cisco IOS / IOS-XE",
    "plat_iosxr": "Cisco IOS-XR",
    "plat_nxos": "Cisco NX-OS",
    "plat_junos": "Juniper Junos",
    "plat_eos": "Arista EOS",
    "plat_fortios": "Fortinet FortiOS",
    "plat_panos": "Palo Alto PAN-OS",
    "plat_linux": "Linux (curl / wget / scp)",
    "plat_f5": "F5 BIG-IP",
    "plat_huawei": "Huawei VRP",
    "plat_iosxe_notes": "С помощью \"show flash:\" убедитесь, что в файловой системе flash достаточно свободного места. При использовании SCP на сервере должна быть настроена команда \"ip scp server enable\", либо на устройстве должна быть включена маршрутизация SSH.",
    "plat_iosxr_notes": "Файловые системы IOS-XR используют disk0: или disk1: вместо flash:. Команды SCP/SFTP в XR интерактивно запрашивают пароль пользователя. Контекст маршрутизации (VRF) можно настроить глобально.",
    "plat_nxos_notes": "NX-OS по умолчанию использует bootflash:. Проверьте место в файловой системе командой \"dir bootflash:\". VRF должен иметь IP-доступность до сервера; проверьте маршрутизацию по умолчанию или management VRF.",
    "plat_junos_notes": "Скопированные файлы в Junos размещаются в /var/tmp/ или /var/db/config/. Проверьте место на диске командой \"show system storage\". Для передач TFTP могут потребоваться настройки протоколов маршрутизации Junos или использование ключевого слова routing-instance.",
    "plat_eos_notes": "Устройства Arista используют flash:. Проверьте командой \"dir flash:\". Для высокой пропускной способности Arista поддерживает нативные высокооптимизированные копии по HTTP/HTTPS.",
    "plat_fortios_notes": "Восстановление по TFTP в FortiOS заменяет загрузочный образ и автоматически перезагружает устройство. Используйте с осторожностью. Всегда заранее сохраняйте файлы конфигурации.",
    "plat_panos_notes": "Palo Alto PAN-OS требует явных прав администратора CLI для выполнения команд импорта ПО. ПО также можно загрузить напрямую из официальных обновлений поддержки Palo Alto.",
    "plat_linux_notes": "Проверьте права чтения/записи целевого каталога. Убедитесь, что клиент (scp, curl) установлен. Передачи HTTP/HTTPS через curl/wget хорошо распараллеливаются.",
    "plat_f5_notes": "Проверьте процессы bigstart и разрешения административных маршрутов F5. Целевая папка /shared/images/ — расположение по умолчанию для ISO-файлов F5.",
    "cmd_iosxe": "! Команда Cisco IOS/IOS-XE",
