    "double_nat_title": "Двойной NAT в развертываниях CGNAT",
    "double_nat_body": "В типичном развертывании CGNAT абоненты также выполняют NAT на своем CPE — транслируя адреса {rfc1918} в назначенный им адрес 100.64.0.0/10 еще до того, как трафик достигнет NAT оператора. Этот двойной NAT нарушает работу UPnP и автоматическое сопоставление портов, усложняет ручной проброс портов и является известной проблемой для игр, VoIP и любых приложений, требующих входящих соединений.",
