    "scenario_label": "Выберите сценарий двойного NAT",
    "scenario_overlap_title": "Сценарий 1: Пересекающиеся подсети (IPsec VPN)",
    "scenario_overlap_desc": "Две сети используют один и тот же частный диапазон (напр., 192.168.1.0/24). Для связи без конфликтов IP обе стороны должны выполнять NAT. Хост A транслируется в транзитный IP, и хост B транслируется в транзитный IP.",
