    "scenario_cgnat_desc": "Провайдер выделяет клиенту 100.64.0.0/10 (RFC 6598) для WAN. Клиент выполняет локальный NAT (192.168.1.0/24 -> 100.64.1.2), а провайдер выполняет CGNAT (100.64.1.2 -> публичный IP) для экономии пространства IPv4.",
