    "explanation_title": "Понимание NAT и PAT",
    "explanation_intro": "Network Address Translation (NAT) и Port Address Translation (PAT) — это методы сопоставления одного пространства IP-адресов другому, используемые в основном для сохранения ограниченных публичных адресов IPv4 или разрешения конфликтов подсетей.",
    "nat_expl_title": "1. Что такое NAT?",
    "nat_expl_desc": "NAT транслирует IP-адреса в соотношении 1-к-1. Он может быть статическим (постоянное сопоставление одного частного IP одному публичному IP, идеально для публичных серверов) или динамическим (выделяет публичный IP из пула частному хосту по запросу. Когда все публичные IP назначены, последующие хосты блокируются до освобождения адреса). Номера портов не изменяются.",
    "pat_expl_title": "2. Что такое PAT (NAT Overload)?",
    "pat_expl_desc": "PAT (или Port Address Translation / NAT Overload) транслирует как IP-адрес, так и номер исходного порта в соотношении «многие-к-одному» (N-к-1). Несколько частных хостов совместно используют один публичный IP-адрес путем назначения уникальных исходных портов (напр., 192.168.1.10:5000 и 192.168.1.11:5000 сопоставляются с 203.0.113.10:1024 и 203.0.113.10:1025). Это стандартный метод для домашних роутеров и корпоративного доступа в Интернет.",
    "comparison_table_title": "Сводное сравнение",
    "comp_header_feature": "Функция",
    "comp_header_nat": "NAT (1-к-1)",
    "comp_header_pat": "PAT (N-к-1 / Overload)",
    "comp_row_ratio": "Соотношение IP-адресов",
    "comp_row_ratio_nat": "1:1 (Один публичный IP на активный хост)",
    "comp_row_ratio_pat": "Многие-к-одному / Многие-к-нескольким (N:1)",
    "comp_row_port": "Изменение порта",
    "comp_row_port_nat": "Нет (исходный порт сохраняется)",
    "comp_row_port_pat": "Да (динамически переписывается для уникальности)",
    "comp_row_limit": "Лимит емкости",
    "comp_row_limit_nat": "Равен количеству IP в публичном пуле",
    "comp_row_limit_pat": "До ~64 500 сессий на один публичный IP",
    "comp_row_use": "Основной сценарий",
