    "cheatsheet_title": "Шпаргалка",
    "cheatsheet_intro": "Типовые шаблоны команд iperf3 и iperf2 для тестирования пропускной способности, джиттера и потери пакетов.",
    "about_body": "iperf — это инструмент активного измерения максимально достижимой пропускной способности в IP-сетях. Один хост работает как сервер (слушатель), а другой подключается как клиент для передачи (или приема) трафика по протоколам TCP, UDP или SCTP, сообщая о пропускной способности, джиттере и потере пакетов. iperf3 (исполняемый файл iperf3) — это современная версия с выводом в формате JSON и реверсивным/двунаправленным режимами; iperf2 (исполняемый файл iperf) поддерживает несколько клиентов и лучше подходит для тестирования Wi-Fi и мультикаста. Эти две версии НЕ совместимы друг с другом — на обоих концах должна быть запущена одна и та же версия.",
