    "note_2": "Управляющий трафик и трафик данных используют один и тот же порт (по умолчанию 5201 для iperf3, 5001 для iperf2) — откройте в брандмауэре и TCP, и UDP для этого порта.",
    "note_3": "Для тестов UDP требуется явно указать целевую пропускную способность -b; без этого иperf2 и iperf3 по умолчанию используют 1 Мбит/с.",
